import React, { useState, useMemo } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';

// --- Placeholder Tab Content Components ---
// These components are placeholders for the actual content of each tab.
const PlaceholderTabContent = ({ title }) => (
  <div style={{ padding: '2rem', backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #dee2e6' }}>
    <h3 style={{ marginTop: 0, color: '#495057' }}>{title}</h3>
    <p style={{ color: '#6c757d' }}>Content for this section will be built out here.</p>
  </div>
);
const BaseAllocationTab = () => <PlaceholderTabContent title="Base Allocation" />;
const PerDeliveryAllocationTab = () => <PlaceholderTabContent title="Per-delivery Allocation" />;
const StaffRolesTab = () => <PlaceholderTabContent title="Staff Roles" />;
const PerStudentAllocationTab = () => <PlaceholderTabContent title="Per-student Allocation" />;
const ActivityAllocationTab = () => <PlaceholderTabContent title="Activity Allocation" />;
const PerGroupAllocationTab = () => <PlaceholderTabContent title="Per-group Allocation" />;

// --- Icon and Helper Components ---
const BackIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <polyline points="15 18 9 12 15 6" />
    </svg>
);

// --- Main Subject Workload Page Component ---
export default function SubjectWorkloadPage() {
    const navigate = useNavigate();
    const location = useLocation();

    // Retrieve the subject data passed from the previous page
    const { subject } = location.state || {};

    // State to manage the completion status and the currently active tab
    const [subjectWorkloadStatus, setSubjectWorkloadStatus] = useState('incomplete');

    // Determine which tabs to display based on the subject's delivery format
    const TABS_CONFIG = useMemo(() => {
        if (!subject) return {};
        const isLectureBased = subject.formatOfDelivery.toLowerCase().includes('lecture');

        if (isLectureBased) {
            return {
                "Base Allocation": <BaseAllocationTab />,
                "Per-delivery Allocation": <PerDeliveryAllocationTab />,
                "Staff Roles": <StaffRolesTab />,
                "Per-student Allocation": <PerStudentAllocationTab />,
                "Activity Allocation": <ActivityAllocationTab />
            };
        } else { // Project-based
            return {
                "Base Allocation": <BaseAllocationTab />,
                "Per-group Allocation": <PerGroupAllocationTab />
            };
        }
    }, [subject]);

    const tabNames = Object.keys(TABS_CONFIG);
    const [activeTab, setActiveTab] = useState(tabNames[0]);

    // Mock summary data, as this would likely be calculated or fetched
    const subjectSummaryData = {
        total_subject_workload: subject?.totalSubjectWorkload || 'N/A',
        total_eftsl_for_subject: "12.5",
        total_administrative_loadings: "0.0%"
    };

    // If the user navigates to this page directly without data, show a message.
    if (!subject) {
        return (
            <div style={styles.container}>
                <h1 style={styles.title}>Error</h1>
                <p>No subject data provided. Please go back to the subject list and select a subject.</p>
                <button style={styles.button()} onClick={() => navigate('/')}>Back to List</button>
            </div>
        );
    }

    const isNextDisabled = subjectWorkloadStatus === 'incomplete';

    return (
        <div style={styles.container}>
            <header style={styles.header}>
                <button style={styles.backButton} onClick={() => navigate('/')}>
                    <BackIcon /> Back to Subject List
                </button>
                <h1 style={styles.title}>
                    Subject Workload - {subject.formatOfDelivery}
                </h1>
            </header>

            <Stepper currentStep={1} />

            <div style={styles.panelsContainer}>
                <InfoPanel title="Subject Information" data={subject} />
                <InfoPanel title="Subject Summary" data={subjectSummaryData} />
            </div>

            <div style={styles.tabsContainer}>
                {tabNames.map(tabName => (
                    <button 
                        key={tabName} 
                        style={activeTab === tabName ? styles.tabButtonActive : styles.tabButton}
                        onClick={() => setActiveTab(tabName)}>
                        {tabName}
                    </button>
                ))}
            </div>

            <main style={styles.tabContent}>
                {TABS_CONFIG[activeTab]}
            </main>

            <footer style={styles.footer}>
                {/* A temporary toggle to simulate completing the step */}
                <div style={{display: 'flex', alignItems: 'center', gap: '0.5rem'}}>
                    <input 
                        type="checkbox" 
                        id="statusToggle"
                        checked={subjectWorkloadStatus === 'complete'}
                        onChange={(e) => setSubjectWorkloadStatus(e.target.checked ? 'complete' : 'incomplete')}
                    />
                    <label htmlFor="statusToggle" style={{color: '#495057'}}>Mark as Complete</label>
                </div>
                <div>
                    <button style={styles.button('secondary')}>Save & Exit</button>
                    <button style={{...styles.button('primary'), marginLeft: '1rem', opacity: isNextDisabled ? 0.5 : 1}} disabled={isNextDisabled}>
                        Next: Workload Distribution
                    </button>
                </div>
            </footer>
        </div>
    );
}


// --- Reusable Child Components ---

function Stepper({ currentStep }) {
    const steps = ["Subject Workload", "Workload Distribution"];
    return (
        <div style={styles.stepperContainer}>
            {steps.map((step, index) => (
                <React.Fragment key={step}>
                    <div style={styles.step}>
                        <div style={index + 1 <= currentStep ? styles.stepNumberActive : styles.stepNumber}>
                            {index + 1}
                        </div>
                        <div style={index + 1 <= currentStep ? styles.stepLabelActive : styles.stepLabel}>
                            {step}
                        </div>
                    </div>
                    {index < steps.length - 1 && <div style={styles.stepperLine} />}
                </React.Fragment>
            ))}
        </div>
    );
}

function InfoPanel({ title, data }) {
    const formatKey = (key) => {
      return key
        .replace(/([A-Z])/g, ' $1') // Add space before uppercase letters
        .replace(/_/g, ' ') // Replace underscores with spaces
        .replace(/\b\w/g, char => char.toUpperCase()); // Capitalize first letter of each word
    };

    return (
        <div style={styles.panel}>
            <h2 style={styles.panelTitle}>{title}</h2>
            <div style={styles.panelGrid}>
                {Object.entries(data).map(([key, value]) => (
                    // Exclude subjectId from display
                    key !== 'subjectId' &&
                    <div key={key} style={styles.panelItem}>
                        <span style={styles.panelKey}>{formatKey(key)}:</span>
                        <span style={styles.panelValue}>{value}</span>
                    </div>
                ))}
            </div>
        </div>
    );
}


